/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        await scwin.init();
        await scwin.setYear();
        await scwin.setHeader();
        scwin.setChrgTpCd();
        await scwin.initModify();

        // 입력모드일때 '삭제'버튼 숨김
        if (scwin.key_edu_partc_id !== "") {
            btn_Delete.show("");
        } else {
            btn_Delete.hide();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30625.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

// 이수시간

