/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30625.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    try {
        const CHAR_NM = dts_ComDisclsPerson.getCellData(row, "CHRG_NM"); // 담당자명
        const EDU_KIND_NM = dts_ComDisclsPerson.getCellData(row, "EDU_KIND_NM"); // 교육구분
        const ISUR_CD = dts_ComDisclsPerson.getCellData(row, "ISUR_CD"); // 회사코드
        const CHRG_TP_CD = dts_ComDisclsPerson.getCellData(row, "CHRG_TP_CD"); // 회사코드

        txb_selectedNm.setValue(CHAR_NM); //+ " [" + EDU_KIND_NM + "]" ;
        tbx_hdn_isur_cd.setValue(ISUR_CD);
        tbx_hdn_chrg_tp_cd.setValue(CHRG_TP_CD);

        // 선택한 교육참가자의 담당자구분코드를 취득하여 콤보박스의 값을 설정
        scwin.setChrgTpCd2(tbx_hdn_chrg_tp_cd.getValue()); // 콤보 초기화
        await scwin.search2(); // 교육과정 조회
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30625.grd_Grid_OnClick" });
    }
};

