    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30625.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30625.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30625.txb_isur_cd_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setYear
 * @description set Year 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setYear = async function() {
    const sbmOptions = {
        id : "sbm_dts_year",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_year=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const minYear = dts_year.getCellData(1, "MIN_YEAR");
    const maxYear = dts_year.getCellData(1, "MAX_YEAR");
    let str = "^전체";
    for (let i = maxYear; i >= minYear; i--) {
        str += "," + i + "%^" + i;
    }
    // alert(str);
    cmb_YYYY.CBData = str;

    // default 현재년도
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    cmb_YYYY.setValue(yyyy + "%");
};

/**
 * @method
 * @name search
 * @description 담당자 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&EDU_KIND_CD=";
    url += "&YYYY=";
    url += "&EMP_NO=";
    url += "&DEP_CD=";
    url += "&CHRG_NM=" + txb_chrg_nm.getValue();
    url += "&SCREN_ID=" + "ULDSTF30625.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_ComDisclsPerson",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_ComDisclsPerson=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

// 교육 검색(파라미터가 있을경우, 해당 ID로 조회)

/**
 * @method
 * @name search2
 * @description search2 처리
 * @param {*} edu_schdl_id edu_schdl_id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search2 = async function(edu_schdl_id) {
    if (txb_selectedNm.getValue() === '') {
        await $c.win.alert("교육참가자 선택 후 조회 가능합니다.");
        return;
    }
    url += "&EDU_KIND_CD=" + cmb_EDU_KIND_CD.getValue();
    url += "&OBJ_YY=" + cmb_YYYY.getValue();
    if (edu_schdl_id !== null) {
        // 조회버튼 클릭 시 PK값의 할당을 방지하기 위해 IF문 사용
        url += "&EDU_SCHDL_ID=" + edu_schdl_id;
    }
    url += "&SCREN_ID=" + "ULDSTF30625.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Edu_Plan",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Edu_Plan=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

