///////// 5. 일반/업무 함수 영역 /////////
// 담당자구분 초기화(최초)

/**
 * @method
 * @name setChrgTpCd
 * @description set Chrg Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setChrgTpCd = function() {
    cmb_EDU_KIND_CD.ClearData();
    cmb_EDU_KIND_CD.CBData = "^전체,11^공시책임자교육,12^공시담당자(정)교육,13^공시담당자(부)교육,14^공시대리인교육,15^공시담당보조자교육";
};

// 담당자구분 초기화(최초 이후, 교육참가자 선택 시)

/**
 * @method
 * @name setChrgTpCd2
 * @description set Chrg Tp Cd2 처리
 * @param {*} chrg_tp_cd chrg_tp_cd
 * @returns {void}
 * @hidden N
 */
scwin.setChrgTpCd2 = function(chrg_tp_cd) {
    cmb_EDU_KIND_CD.ClearData();
    let str = "";
    if (chrg_tp_cd === "11") {
        str = "11^공시책임자교육";
    } else {
        str = "12^공시담당자(정)교육,13^공시담당자(부)교육,14^공시대리인교육,15^공시담당보조자교육";
    }
    cmb_EDU_KIND_CD.CBData = str;
};

/**
 * @method
 * @name initModify
 * @description 수정일 경우 기존 값 셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initModify = async function() {
    // 수정일 경우에만 실행
    if (scwin.key_edu_partc_id !== "") {
        // 1. 수정자 정보 화면표시 셋팅
        txb_selectedNm.setValue(scwin.key_chrg_nm);
        tbx_hdn_isur_cd.setValue(scwin.key_isur_cd);
        tbx_hdn_chrg_tp_cd.setValue(scwin.key_chrg_tp_cd);
        txb_selectedEduNm.setValue(scwin.key_edu_nm);
        txb_selectedEduAckTm.setValue(scwin.key_edu_ack_tm);
        tbx_hdn_edu_id.setValue(scwin.key_edu_id);

        // 2. 교육참가자 그리드 셋팅
        txb_isur_cd.setValue(scwin.key_isur_cd);
        txb_com_abbrv.setValue(scwin.key_com_abbrv);
        txb_chrg_nm.setValue(scwin.key_chrg_nm);
        await scwin.search();
        await scwin.search2(tbx_hdn_edu_id.getValue());

        // 3. 담당자구분 콤보박스 셋팅
        scwin.setChrgTpCd2(scwin.key_chrg_tp_cd);
    }
};

/**
 * @method
 * @name save
 * @description 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_selectedNm.getValue() === '') {
        await $c.win.alert('교육참가자를 선택하시기 바랍니다.');
        return;
    }
    if (txb_selectedEduNm.getValue() === '') {
        await $c.win.alert('교육과정을 선택하시기 바랍니다.');
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        scwin.gLastJob = "저장";
        let url = "/ListedCompany.do?method=saveDisclsEduPartc";
        url += "&EDU_PARTC_ID=" + scwin.key_edu_partc_id;
        url += "&SCREN_ID=" + "ULDSTF30625.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
        trs_Save.Post();
    }
};

/**
 * @method
 * @name delete
 * @description 삭제 버튼 클릭 시
 * @returns {void}
 * @hidden N
 */
scwin.delete = function() {
    if (window.confirm("[삭제]하시겠습니까?")) {
        scwin.gLastJob = "삭제";
        let url = "/ListedCompany.do?method=deleteDisclsEduPartc";
        url += "&EDU_PARTC_ID=" + scwin.key_edu_partc_id;
        url += "&SCREN_ID=" + "ULDSTF30625.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
        trs_Save.post();
    }
};
